// Title Splash Overlay (Dismissed with any single key or click!)
function renderTitleOverlay() {
  ctx.save();
  ctx.fillStyle = "rgba(7, 11, 25, 0.78)";
  ctx.fillRect(0, 0, W, H);

  const bx = W / 2 - 340;
  const by = 135;
  const bw = 680;
  const bh = 440;
  ctx.fillStyle = "rgba(15, 23, 42, 0.95)";
  ctx.fillRect(bx, by, bw, bh);
  ctx.strokeStyle = "#38bdf8";
  ctx.lineWidth = 4;
  ctx.strokeRect(bx, by, bw, bh);

  // Top Gold Anniversary Ribbon
  ctx.fillStyle = "#facc15";
  ctx.fillRect(bx, by, bw, 36);
  ctx.fillStyle = "#0f172a";
  ctx.font = "bold 16px monospace";
  ctx.textAlign = "center";
  ctx.fillText("★ 25TH ANNIVERSARY CROSSOVER ACTION RPG REVIVAL ★", W / 2, by + 24);

  // Game Title
  ctx.fillStyle = "#38bdf8";
  ctx.font = "bold 44px monospace";
  ctx.fillText("CYBER-OVER: MEMORY HORIZON", W / 2, by + 95);

  // Hero OVER-1 & OVER-10 Showcase
  Sprites.drawOverCharacter(ctx, W / 2 - 140, by + 235, {
    armor: GameData.ARMORS[0],
    animTime: performance.now() * 0.001,
    running: true,
    chargeTier: 3,
    scale: 1.5,
  });
  Sprites.drawOverCharacter(ctx, W / 2 + 140, by + 235, {
    armor: GameData.ARMORS[4],
    animTime: performance.now() * 0.001,
    running: true,
    chargeTier: 2,
    facing: -1,
    scale: 1.5,
  });

  ctx.fillStyle = "#e2e8f0";
  ctx.font = "15px monospace";
  ctx.fillText("Auto-Charge Pierce Shots • 6-Beam Giga Crush • Bonus Line Card Decks • 4P Master Raids", W / 2, by + 295);
  ctx.fillStyle = "#93c5fd";
  ctx.font = "14px monospace";
  ctx.fillText("Controls: [SPACE / ↑] Jump   [X / →] Charge Shot   [C / SHIFT] Giga Crush / C.Shot", W / 2, by + 328);

  // Pulsing Start Button
  const pulse = 1 + Math.sin(performance.now() * 0.006) * 0.04;
  ctx.save();
  ctx.translate(W / 2, by + 382);
  ctx.scale(pulse, pulse);
  ctx.fillStyle = "#2563eb";
  ctx.fillRect(-190, -26, 380, 52);
  ctx.strokeStyle = "#facc15";
  ctx.lineWidth = 3;
  ctx.strokeRect(-190, -26, 380, 52);
  ctx.fillStyle = "#ffffff";
  ctx.font = "bold 20px monospace";
  ctx.fillText("▶ PRESS ANY KEY OR CLICK TO WARP IN", 0, 7);
  ctx.restore();

  ctx.restore();
}

